import type {
  IncomingMessage,
  ListSessionsMessage,
  OutgoingMessage,
  SessionListMessage,
  SessionSummaryFrame,
} from './index.js';
import * as subprotocol from './transport/ws/subprotocol.js';

describe('the package root', () => {
  it('exports the hal.v1 marker with the reader a WsAuthenticator uses', () => {
    expect({marker: HAL_WS_SUBPROTOCOL, reader: credentialFromSubprotocol}).toEqual({
      marker: subprotocol.HAL_WS_SUBPROTOCOL,
      reader: subprotocol.credentialFromSubprotocol,
    });
  });

  it('exports ListSessionsMessage, SessionSummaryFrame, and SessionListMessage in the incoming and outgoing message unions', () => {
    const incoming: IncomingMessage = {
      type: 'list_sessions',
      limit: 10,
      before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
    } satisfies ListSessionsMessage;
    const summary: SessionSummaryFrame = {
      sessionId: 's1',
      createdAt: '2026-01-01T00:00:00.000Z',
      updatedAt: '2026-01-01T00:00:00.000Z',
      entryCount: 2,
    };
    const outgoing: OutgoingMessage = {
      type: 'session_list',
      sessions: [summary],
    } satisfies SessionListMessage;

    expect({incoming, outgoing}).toEqual({
      incoming: {
        type: 'list_sessions',
        limit: 10,
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
      },
      outgoing: {
        type: 'session_list',
        sessions: [
          {
            sessionId: 's1',
            createdAt: '2026-01-01T00:00:00.000Z',
            updatedAt: '2026-01-01T00:00:00.000Z',
            entryCount: 2,
          },
        ],
      },
    });
  });
});

